const sourceUrl = 'https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml';

function first(x) {
  return Array.isArray(x) ? x[0] : x;
}

function attr(obj, name) {
  if (!obj) return undefined;
  return obj[name] ?? obj.$?.[name] ?? obj.$?.[`@_${name}`] ?? obj[`@_${name}`];
}

const root =
  $json['gesmes:Envelope'] ??
  $json.Envelope ??
  $json;

const cubeRoot = first(root.Cube);
const timeCube = first(cubeRoot?.Cube);

if (!timeCube) {
  throw new Error(
    'ECB timeCube nicht gefunden. XML-Struktur: ' +
    JSON.stringify($json).slice(0, 2000)
  );
}

const rateDate = attr(timeCube, 'time');

if (!rateDate) {
  throw new Error(
    'RateDate/time nicht gefunden. timeCube: ' +
    JSON.stringify(timeCube).slice(0, 2000)
  );
}

const rates = Array.isArray(timeCube.Cube)
  ? timeCube.Cube
  : timeCube.Cube
    ? [timeCube.Cube]
    : [];

const out = [];

out.push({
  json: {
    RateDate: rateDate,
    BaseCurrencyISOCode: 'EUR',
    QuoteCurrencyISOCode: 'EUR',
    Rate: 1.0,
    Source: 'ECB',
    SourceUrl: sourceUrl
  }
});

for (const r of rates) {
  const currency = attr(r, 'currency');
  const rate = attr(r, 'rate');

  if (!currency || rate === undefined) continue;

  out.push({
    json: {
      RateDate: rateDate,
      BaseCurrencyISOCode: 'EUR',
      QuoteCurrencyISOCode: currency,
      Rate: Number(rate),
      Source: 'ECB',
      SourceUrl: sourceUrl
    }
  });
}

return out;

