const rates = $input.all().map(item => item.json);
const fromWaehrung = $('Loop Over Items').item.json.BestellungBezahlungWaehrung ?? '';
const betrag = $('Loop Over Items').item.json.BestellungBezahlungBetrag ?? 0;

const eurUsd = rates.find(r => r.FXRateQuoteCurrencyISOCode === 'USD');
const eurAny = rates.find(r => r.FXRateQuoteCurrencyISOCode !== 'USD');

if (!eurUsd || !eurAny) {
  throw new Error('EUR/USD oder EUR/' + fromWaehrung + ' Kurs fehlt');
}

const usdPerAny =
  Number(eurUsd.FXRateRate) / Number(eurAny.FXRateRate);

const betragUsd = Number(betrag) * Number(usdPerAny);

return [{
  json: {
    FxRateDate: eurUsd.FxRateDate,
    FXRateBaseCurrencyISOCode: fromWaehrung,
    FXRateQuoteCurrencyISOCode: 'USD',
    FXRateRate: usdPerAny.toFixed(10),
    betragUsd: betragUsd
  }
}];

